#define MAXN 2000
#define INF 1000000000

typedef struct Edge {
    int to, dist;
    struct Edge *next;
} Edge;

Edge *adj[MAXN + 1];
int dist[MAXN + 1];
int visited[MAXN + 1];

void add_edge(int u, int v, int d) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->dist = d;
    e->next = adj[u];
    adj[u] = e;
}

void dijkstra(int start, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }
    dist[start] = 0;

    for (int i = 1; i <= n; i++) {
        int u = -1;
        int minDist = INF;
        for (int j = 1; j <= n; j++) {
            if (!visited[j] && dist[j] < minDist) {
                minDist = dist[j];
                u = j;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (Edge *e = adj[u]; e; e = e->next) {
            int v = e->to;
            if (!visited[v] && dist[u] + e->dist < dist[v]) {
                dist[v] = dist[u] + e->dist;
            }
        }
    }
}

