typedef long long ll;

typedef struct Edge {
    int to;
    int w;
    int next;
} Edge;

typedef struct Node {
    ll d;
    int v;
} Node;

typedef struct MinHeap {
    Node *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (Node *)malloc(sizeof(Node) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, ll d, int v) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (Node *)realloc(h->a, sizeof(Node) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].d > d) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].d = d;
    h->a[i].v = v;
}

static Node heap_pop(MinHeap *h) {
    Node ret = h->a[1];
    Node last = h->a[h->size--];
    int i = 1;
    while (i * 2 <= h->size) {
        int c = i * 2;
        if (c + 1 <= h->size && h->a[c + 1].d < h->a[c].d) c++;
        if (h->a[c].d >= last.d) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->size == 0;
}

static void dijkstra(int n, int *head, Edge *edges, int src, ll *dist) {
    const ll INF = (ll)4e18;
    for (int i = 1; i <= n; i++) dist[i] = INF;
    dist[src] = 0;

    MinHeap pq;
    heap_init(&pq, n + 5);
    heap_push(&pq, 0, src);

    while (!heap_empty(&pq)) {
        Node cur = heap_pop(&pq);
        ll d = cur.d;
        int u = cur.v;
        if (d != dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(&pq, nd, v);
            }
        }
    }

    free(pq.a);
}

