public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class State implements Comparable<State> {
        int v;
        long d;
        State(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(State o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(int start, List<Edge>[] g) {
        int n = g.length - 1;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[start] = 0;
        pq.add(new State(start, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new State(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Edge>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            int d = fs.nextInt();
            g[u].add(new Edge(v, d));
        }

        long answer = 0;

        for (int i = 1; i < N; i++) {
            long[] dist = dijkstra(i, g);
            if (dist[i + 1] >= INF) {
                System.out.println(-1);
                return;
            }
            answer += dist[i + 1];
        }

        long[] dist = dijkstra(N, g);
        if (dist[1] >= INF) {
            System.out.println(-1);
            return;
        }
        answer += dist[1];

        System.out.println(answer);
    }
}

